    adcs_vec3_t predicted_body;
    adcs_vec3_t p_norm;
    adcs_vec3_t b_norm;
    double dot_product;
    adcs_vec3_t cross_vec;
    double cross_norm;
    double c_clamped;
    size_t i, j;

    /* Validate pointers */
    if ((c_bi == NULL) || (check_body == NULL) || (check_inertial == NULL) ||
        (angle_residual_rad == NULL) || (cross_residual_body == NULL)) {
        return ADCS_E_NULL;
    }

    /* Set failure defaults as per contract */
    *angle_residual_rad = INFINITY;
    *cross_residual_body = (adcs_vec3_t){0.0, 0.0, 0.0};

    /* Check finiteness of attitude matrix elements */
    for (i = 0; i < 3; i++) {
        for (j = 0; j < 3; j++) {
            if (!isfinite(c_bi->m[i][j])) {
                return ADCS_E_NOT_FINITE;
            }
        }
    }

    /* Check finiteness of input vectors */
    if ((!adcs_is_finite_vec3(check_body)) || (!adcs_is_finite_vec3(check_inertial))) {
        return ADCS_E_NOT_FINITE;
    }

    /* Map inertial check vector to body frame: p_predicted = C_BI * check_inertial */
    predicted_body = adcs_mat3_mul_vec(c_bi, check_inertial);

    /* Normalize the predicted vector */
    if (adcs_vec3_normalize(&predicted_body, ADCS_EPS_NORM, &p_norm) != ADCS_OK) {
        return ADCS_E_RANGE;
    }

    /* Normalize the measured body vector */
    if (adcs_vec3_normalize(check_body, ADCS_EPS_NORM, &b_norm) != ADCS_OK) {
        return ADCS_E_RANGE;
    }

    /* Calculate dot product and clamp to [-1, 1] */
    dot_product = adcs_vec3_dot(&b_norm, &p_norm);
    c_clamped = ADCS_CLAMP(dot_product, -1.0, 1.0);

    /* Calculate cross product vector */
    cross_vec = adcs_vec3_cross(&b_norm, &p_norm);

    /* Calculate angle residual: atan2(||cross||, c) */
    cross_norm = adcs_vec3_norm(&cross_vec);
    *angle_residual_rad = atan2(cross_norm, c_clamped);

    /* Return cross vector as signed small-error direction */
    *cross_residual_body = cross_vec;

    return ADCS_OK;
}

