    adcs_vec3_t p = adcs_mat3_mul_vec(c_bi, check_inertial);

    // Validate mapped vector: must be finite and non-zero
    if ((!adcs_is_finite_vec3(&p)) || (adcs_vec3_norm(&p) <= 0.0)) {
        return ADCS_E_RANGE;
    }

    // Validate check_body: must be finite and non-zero
    if ((!adcs_is_finite_vec3(check_body)) || (adcs_vec3_norm(check_body) <= 0.0)) {
        return ADCS_E_RANGE;
    }

