    adcs_vec3_t b;
    if (adcs_vec3_normalize(check_body, 0.0, &b) != ADCS_OK) {
        return ADCS_E_RANGE;
    }

    // Normalize predicted body vector p = unit(C_BI * unit(check_inertial))
    // Note: Since C_BI is orthogonal, unit(C_BI * v) == C_BI * unit(v).
    // We computed C_BI * check_inertial, now normalize it.
    adcs_vec3_t p_unit;
    if (adcs_vec3_normalize(&p, 0.0, &p_unit) != ADCS_OK) {
        return ADCS_E_RANGE;
    }

    // Compute dot product and clamp to [-1, 1]
    double dot = adcs_vec3_dot(&b, &p_unit);
    if (dot < -1.0) {
        dot = -1.0;
    } else if (dot > 1.0) {
        dot = 1.0;
    }

    // Compute cross product
    adcs_vec3_t cross = adcs_vec3_cross(&b, &p_unit);

    // Compute magnitude of cross product
    double norm_cross = adcs_vec3_norm(&cross);

    // Calculate angle residual using atan2
    *angle_residual_rad = atan2(norm_cross, dot);

    // Assign cross residual
    *cross_residual_body = cross;

    return ADCS_OK;
}

